"""One terminal category per scheduled propagation, fit, and B3 stack (E39-7)."""

from __future__ import annotations

from ckappa_classfit.pinned import SYSTEM_ORDER
from ckappa_classfit.rankcats import TERMINAL_CATEGORIES
from ckappa_classfit.schedule import STAGES, UNITS, scheduled_count


class Ledger:
    def __init__(self) -> None:
        self.scheduled = {}
        self.counts = {}
        self.remaining = {}
        self.attempted_detail = {}
        self.closed = {}
        for system in SYSTEM_ORDER:
            for stage in STAGES:
                for unit in UNITS:
                    key = (system, stage, unit)
                    scheduled = scheduled_count(system, stage, unit)
                    self.scheduled[key] = scheduled
                    self.remaining[key] = scheduled
                    self.counts[key] = {name: 0 for name in TERMINAL_CATEGORIES}
                    self.attempted_detail[key] = {
                        "valid_finite": 0,
                        "guard_invalid": 0,
                        "value_error": 0,
                        "non_finite": 0,
                    }
                    self.closed[key] = False

    def add(self, system: str, stage: str, unit: str, category: str, n: int = 1, detail: str | None = None) -> None:
        if n < 0:
            raise ValueError("negative accounting increment")
        if n == 0:
            return
        key = (system, stage, unit)
        if category not in self.counts[key]:
            raise KeyError(category)
        if n > self.remaining[key]:
            raise RuntimeError(f"accounting overrun at {key}: {n} > {self.remaining[key]}")
        self.remaining[key] -= n
        self.counts[key][category] += n
        if category == "ATTEMPTED" and detail is not None:
            self.attempted_detail[key][detail] += n

    def dump_remaining(self, category: str, system: str | None = None, stage: str | None = None, unit: str | None = None) -> None:
        """Assign every still-unattempted call in the selected slice."""
        for key, left in list(self.remaining.items()):
            if left == 0:
                continue
            sys_name, stage_name, unit_name = key
            if system is not None and sys_name != system:
                continue
            if stage is not None and stage_name != stage:
                continue
            if unit is not None and unit_name != unit:
                continue
            self.add(sys_name, stage_name, unit_name, category, left)

    def close_all(self) -> bool:
        ok = True
        for key, left in self.remaining.items():
            total = sum(self.counts[key].values())
            exact = left == 0 and total == self.scheduled[key]
            self.closed[key] = exact
            if not exact:
                ok = False
        return ok

    def records(self) -> list:
        rows = []
        for system in SYSTEM_ORDER:
            for stage in STAGES:
                for unit in UNITS:
                    key = (system, stage, unit)
                    rows.append(
                        {
                            "system": system,
                            "stage": stage,
                            "unit": unit,
                            "scheduled": self.scheduled[key],
                            "counts": dict(self.counts[key]),
                            "attempted_detail": dict(self.attempted_detail[key]),
                            "remaining": self.remaining[key],
                            "closed": self.closed[key],
                        }
                    )
        return rows

    def snapshot(self) -> dict:
        return {"records": self.records()}

"""Rank categories, B3 status, tolerances, and skip precedence.

Bands are the inherited closed interval [1e-10, 1e-6] (NOTE_1 N2, E39-8).
"""

from __future__ import annotations

BAND_LO = 1e-10
BAND_HI = 1e-6
RCOND = 1e-10

TERMINAL_CATEGORIES = (
    "ATTEMPTED",
    "SKIPPED_PRIOR_STOP",
    "SKIPPED_SYSTEM_INADMISSIBLE",
    "SKIPPED_PREFIX_VOID",
    "SKIPPED_UNAVAILABLE_MAP",
    "UNKNOWN_AFTER_LAST_DURABLE",
)


def rank_category_from_ratios(ratios: list[float] | None, sigma_1: float | None, n_cols: int, empty: bool) -> str:
    """Literal NOTE_1 N2 / C3.3(a′) categories.

    ratios are sigma_i / sigma_1 for the singular values that exist.
    Full column rank requires n_cols ratios, each > 1e-6.
    """
    if empty:
        return "UNAVAILABLE_EMPTY"
    if sigma_1 is None:
        raise ValueError("nonempty design missing sigma_1")
    if float(sigma_1) == 0.0:
        return "ZERO_NONEMPTY"
    if not ratios:
        return "ZERO_NONEMPTY"
    if any(BAND_LO <= float(value) <= BAND_HI for value in ratios):
        return "UNRESOLVED"
    resolved = sum(1 for value in ratios if float(value) > BAND_HI)
    if resolved == n_cols and len(ratios) >= n_cols:
        return "FULL"
    return "LOWER"


def category_is_full(category: str) -> bool:
    return category == "FULL"


def category_blocks_propagation(category: str) -> bool:
    """Empty and unresolved maps are not propagated. Lower rank and zero are."""
    return category in ("UNAVAILABLE_EMPTY", "UNRESOLVED")


def b3_status(sigma: list[float] | None, formed: bool) -> str:
    """C3.11(c)–(d). An unformed stack is NOT_FORMED and is not a stop.

    A formed stack with fewer than three singular values has no third ratio.
    That is not the resolved-third-direction stop. Status PASS is the enum
    value for a formed stack that is not ZERO, UNRESOLVED-B3, or a resolved
    third direction. CI-B3-SHORT-STACK records that choice.
    """
    if not formed or sigma is None:
        return "NOT_FORMED"
    if not sigma or float(sigma[0]) == 0.0:
        return "ZERO"
    sigma1 = float(sigma[0])
    if len(sigma) < 3:
        return "PASS"
    third = float(sigma[2]) / sigma1
    if third > BAND_HI:
        return "RESOLVED_THIRD_DIRECTION"
    if BAND_LO <= third <= BAND_HI:
        return "UNRESOLVED-B3"
    return "PASS"


def comparison_tolerance(max_a: float, max_b: float) -> float:
    return 1e-12 + 1e-10 * max(max_a, max_b)


def cancellation_tolerance(scales: list[float]) -> float:
    return 1e-12 + 1e-10 * sum(scales)


def zero_gain_tolerance(response_energy: float) -> float:
    return 1e-18 + 1e-9 * response_energy


def recovery_ok(max_abs: float) -> bool:
    return max_abs <= 1e-9


def zero_gain_ok(loss_mu: float, loss_full: float, response_energy: float) -> bool:
    return abs(loss_mu - loss_full) <= zero_gain_tolerance(response_energy)


def skip_reason(
    *,
    stopped: bool,
    system_inadmissible: bool,
    prefix_void: bool,
    map_unavailable: bool,
) -> str | None:
    """First applicable unattempted reason. None means the call is attempted.

    Precedence (E39-7): prior stop, whole-system inadmissibility, prefix
    void, unavailable map.
    """
    if stopped:
        return "SKIPPED_PRIOR_STOP"
    if system_inadmissible:
        return "SKIPPED_SYSTEM_INADMISSIBLE"
    if prefix_void:
        return "SKIPPED_PREFIX_VOID"
    if map_unavailable:
        return "SKIPPED_UNAVAILABLE_MAP"
    return None

