class PackageStop(Exception):
    def __init__(self, kind: str, exit_code: int, detail: dict | None = None):
        super().__init__(kind)
        self.kind = kind
        self.exit_code = exit_code
        self.detail = detail or {}


# M3. Distinct from exits 0–6. The ruling names the stop kind and not this integer.
INTEGRITY_STOP_KIND = "INTEGRITY STOP"
INTEGRITY_STOP_EXIT = 7


def integrity_stop(reason: str, **detail) -> None:
    """Fail-closed check that is not N1. No outcome label is attached here."""
    payload = {"classification": "non-N1", "reason": reason}
    payload.update(detail)
    raise PackageStop(INTEGRITY_STOP_KIND, INTEGRITY_STOP_EXIT, payload)


def _nonfinite_to_null(value: float):
    if not math.isfinite(value):
        return None
    return value


def json_ready(obj):
    """Convert a JSON-ready structure. Non-finite floats are serialized as null."""
    if obj is None or isinstance(obj, (str, int, bool)):
        return obj

def _guard_detail(beliefs, thetas, forecasts, predictor, prefix, continuation, direction_index, sign, eps):
    actual_belief = beliefs.get("actual")
    predicted_belief = beliefs.get(predictor)
    actual_theta = thetas.get("actual")
    predicted_theta = thetas.get(predictor)
    actual_q = forecasts.get("actual")
    predicted_q = forecasts.get(predictor)
    residual = None
    if actual_q is not None and predicted_q is not None:
        residual = float(np.max(np.abs(actual_q - predicted_q)))
    chart = None
    if actual_theta is not None and predicted_theta is not None:
        chart = float(np.max(np.abs(actual_theta - predicted_theta)))
    return {
        "edit": {
            "prefix": prefix,
            "continuation": continuation,
            "direction": direction_index,
            "sign": sign,
            "eps_syn": eps,
        },
        "min_p_actual": None if actual_belief is None else _min_p(actual_belief),
        "min_p_predicted": None if predicted_belief is None else _min_p(predicted_belief),
        "chart_diff_max_abs": chart,
        "recovery_residual_max_abs": residual,
    }


def _guard_and_maybe_stop(guards, key, actual_ok, pred_ok, beliefs, thetas, forecasts, predictor, prefix, continuation, direction_index, sign, eps, category):
    if category != "FULL":
        return
    cell = guards[key]
    if actual_ok:
        cell.n_actual_valid += 1
        if not pred_ok:
            cell.n_stop += 1
            if cell.first is None:
                # RL-12. Build the record only on the mismatch.
                cell.first = _guard_detail(
                    beliefs, thetas, forecasts, predictor, prefix, continuation, direction_index, sign, eps
                )
            stopped = dict(cell.first)
            stopped["description"] = "a guard inconsistency"
            stopped["not"] = "proof that the recovery tolerance was exceeded"
            stopped["diagnosis"] = "PIPELINE INVALID (guard inconsistency)"
            # RL-8. Guard failure is operational PIPELINE INVALID, exit 2.
            _pipeline("guard inconsistency", 2, **stopped)
    elif pred_ok:
        # RL-2. Actual invalid and predictor valid is recorded and does not stop.
        cell.n_reverse += 1
        if cell.first_reverse is None:
            cell.first_reverse = _guard_detail(
                beliefs, thetas, forecasts, predictor, prefix, continuation, direction_index, sign, eps
            )


def _recovery(name, system, finite, guards, fit_type, fold, klass, eps, predictor, category, actual_ok, beliefs, forecasts, thetas, prefix, continuation, direction_index, sign):
    pred_ok = beliefs[predictor] is not None and _valid(beliefs[predictor])
    guard_key = (predictor, fit_type, fold, klass, eps)
    if guard_key in guards:
        _guard_and_maybe_stop(guards, guard_key, actual_ok, pred_ok, beliefs, thetas, forecasts, predictor, prefix, continuation, direction_index, sign, eps, category)
    if category != "FULL" or not actual_ok:
        return
    actual_q = forecasts.get("actual")
    pred_q = forecasts.get(predictor)
    if actual_q is None or pred_q is None:
        return
    cell = finite[("rec", fit_type, fold, klass, eps, predictor)]
    cell.n_tested += 1
    err = float(np.max(np.abs(actual_q - pred_q)))
    if cell.max_abs is None or err >= cell.max_abs:
        cell.max_abs = err
        cell.worst = {"prefix": prefix, "continuation": continuation, "direction": direction_index, "sign": sign, "eps_syn": eps}
    if not recovery_ok(err):
        _pipeline("finite recovery", 2, system=name, predictor=predictor, fold=fold, klass=klass, eps_syn=eps, max_abs=err, tolerance=RECOVERY, edit=cell.worst)


